import json, os, collections, math
H = os.path.dirname(os.path.abspath(__file__))
m = json.load(open(os.path.join(H, 'stage5a.bm.json'))); pl = m['mep']['plumbing']
ft = pl['fixture_types']; L = []
def gp(x, y):
    gx = min(((abs(x - v), n, v) for n, v in (('1', 0), ('2', 4.2), ('3', 6.5), ('4', 10.8))))
    gy = min(((abs(y - v), n, v) for n, v in (('A', 0), ('B', 1.5), ('C', 5.8))))
    return f"GL {gx[1]} {'+' if x >= gx[2] else '−'}{abs(x - gx[2]):.2f} · GL {gy[1]} {'+' if y >= gy[2] else '−'}{abs(y - gy[2]):.2f}"
ln = lambda p: sum(math.dist(p['pts'][i], p['pts'][i + 1]) for i in range(len(p['pts']) - 1))
c = collections.Counter(f['type'] for f in pl['fixtures'])
tot = collections.defaultdict(float)
for p in pl['pipes']: tot[(p['system'], p['dia'], p['status'])] += ln(p)
SYS = {'cw': 'ประปา', 'soil': 'โสโครก', 'waste': 'น้ำทิ้ง'}
L += ['# ตารางตรวจ Step 5 — ห้องน้ำ ท12 · ส่วนที่ 1 สุขาภิบาล', '',
      'อ่านจาก SN.2.01 แปลนระบบสุขาภิบาล (น้ำเสีย) และ SN.2.02 (น้ำดี) · เปิดด้วยเว็บ v6.39 ขึ้นไป · ไฟล์ฝังผลถอดปริมาณแล้ว (BOQ / Gantt ขึ้นได้เลย)', '',
      '**ยังไม่ได้ทำในส่วนนี้:** ระบบไฟฟ้า E.2.01 (ส่วนที่ 2) · แบบขยายติดตั้งถังบำบัด/ถังเก็บน้ำ SN.3.01 (ฐานรองถัง)', '',
      '## สรุป', '', '| รายการ | จำนวน |', '|---|---|']
for t, n in sorted(c.items()): L.append(f"| {ft[t]['desc']} ({t}) | {n} ชุด |")
for e, n in collections.Counter((e['kind'], e['size']) for e in pl['equipment']).items(): L.append(f"| {dict(water_tank='ถังเก็บน้ำ', pump='ปั๊มน้ำ', gate_valve='ประตูน้ำ', septic_tank='ถังบำบัดน้ำเสีย')[e[0]]} {e[1]} | {n} ชุด |")
for (s, d, st), v in sorted(tot.items()): L.append(f"| ท่อ{SYS[s]} PVC ⌀ {d}{' (สมมติ)' if st == 'assumed' else ''} | {v:.2f} ม. (ยาวตามแนวท่อ ยังไม่เผื่อ) |")
L += ['', '## สุขภัณฑ์ทีละจุด', '', '| รหัส | ชนิด | ห้อง | ระดับพื้น | ตำแหน่ง | สถานะ |', '|---|---|---|---|---|---|']
for f in pl['fixtures']: L.append(f"| {f['id']} | {ft[f['type']]['desc']} | {f['room']} | +{f['xyz'][2]:.2f} | {gp(f['xyz'][0], f['xyz'][1])} | {f['status']} |")
L += ['', '## อุปกรณ์', '', '| รหัส | รายการ | ตำแหน่ง | หมายเหตุ |', '|---|---|---|---|']
for e in pl['equipment']: L.append(f"| {e['id']} | {e['kind']} {e['size']} | {gp(e['xyz'][0], e['xyz'][1])} | {e.get('note', '')} |")
L += ['', '## ท่อ (ไม่รวมท่อแยก 1/2" เข้าสุขภัณฑ์ทีละจุด ซึ่งใช้รหัส CW-<รหัสสุขภัณฑ์>)', '', '| รหัส | ระบบ | ขนาด | ยาว (ม.) | จาก → ถึง | สถานะ | หมายเหตุ |', '|---|---|---|---|---|---|---|']
for p in pl['pipes']:
    if p['system'] == 'cw' and p['dia'] == '1/2"': continue
    a, b = p['pts'][0], p['pts'][-1]
    L.append(f"| {p['id']} | {SYS[p['system']]} | {p['dia']} | {ln(p):.2f} | {gp(a[0], a[1])} → {gp(b[0], b[1])} | {p['status']} | {p.get('note', '').replace('|', '¦')} |")
L += ['', '## ❓ คำถาม', '',
      '1. **จุดกลมที่ปลายท่อน้ำทิ้ง** 5 จุด — รางระบายน้ำห้องน้ำชาย (+0.20) FD-M1 FD-M2 · รางห้องน้ำหญิง FD-F1 FD-F2 · ห้องน้ำคนพิการ (+0.25) FD-D (ตำแหน่งตามตารางสุขภัณฑ์) ผมตีความเป็น **ตะแกรงระบายน้ำ 5 ชุด** แบบไม่มีสัญลักษณ์ FD ในรายการประกอบแบบ — ถูกหรือไม่ หรือเป็นแค่จุดเริ่มท่อ (ไม่คิดตะแกรง)',
      '2. **ท่อน้ำทิ้งจากอ่างล้างหน้าบนเคาน์เตอร์ 10 ใบ** แบบเขียนเฉพาะท่อรับที่ปลายเคาน์เตอร์ (W-M2 GL 2 −0.20 · W-F2 GL 3 +0.20) ไม่ได้เขียนท่อจากอ่างแต่ละใบ — ผมสมมติเดินใต้เคาน์เตอร์ 4 เส้น (W-LMI W-LMO W-LFI W-LFO รวม ' + f"{sum(ln(p) for p in pl['pipes'] if p['id'].startswith('W-L')):.2f}" + ' ม.) ใช้ได้หรือไม่',
      '3. **ระดับแนวท่อและความสูงจุดจ่ายน้ำ** แบบไม่ระบุ ผมสมมติ: ท่อประปาเดินที่ −0.10 · ท่อระบายที่ −0.30 · จุดจ่ายน้ำเหนือพื้น โถส้วม 0.20 สายฉีด 0.45 อ่าง 0.55 โถปัสสาวะ 1.10 ก๊อก 0.45 (มีผลกับความยาวท่อแนวดิ่ง) — ขอค่ามาตรฐานของ Earth',
      '4. **ชั้นคุณภาพท่อ** แบบเขียนแค่ "PVC" — ผมใช้ ประปา PVC ชั้น 13.5 · ระบายน้ำ PVC ชั้น 8.5 ถูกหรือไม่',
      '5. **ก๊อกน้ำ 3 จุด** FC-W (ผนังนอกด้านกริด 1 ระดับทางเดิน +0.05) · FC-M FC-F (สองฝั่งผนังกั้นชาย/หญิง +0.20 ห่าง GL C ลงมา 2.20) แบบ SN ไม่บอกชนิด — คิดเป็นก๊อกน้ำธรรมดา (ก๊อกล้างพื้น) ถูกหรือไม่',
      '6. **รุ่น/ชนิดสุขภัณฑ์** (โถส้วม อ่าง โถปัสสาวะ สายฉีด) แบบ SN ไม่ระบุรุ่น — ใส่เป็นชนิดทั่วไปไว้ก่อน ราคาเลือกตอนผูกราคาใน BOQ',
      '', '## จุดแบบขัดแย้ง', '',
      '- **มาร์ก:** ไฟล์ DWG มีแปลน SN.2.01 ซ้อนกัน 4 แบบ (ตำแหน่งถังบำบัดต่างกัน) — ใช้แบบที่ตรงกับ PDF: ถังบำบัด 2 ถัง (ST-1 หลังอาคารระหว่าง GL 1–2 · ST-2 นอก GL 4) น้ำทิ้งและน้ำออกจากถังต่อเข้าระบบระบายน้ำภายในโครงการ',
      '- **มาร์ก:** รายการประกอบแบบมี "ท่อระบายน้ำทิ้ง ซีเมนต์ใยหิน 8 นิ้ว" และ "บ่อพักสำเร็จรูป 40×50 ซม." แต่แปลนใน PDF ไม่มีทั้งสองอย่าง (มีเฉพาะใน DWG แบบที่ไม่ได้ใช้) — **ไม่ได้ใส่ในโมเดล**',
      '- **มาร์ก:** ท่อจากโถปัสสาวะแบบเขียน "(S) PVC 2 นิ้ว" ต่อเข้าท่อโสโครก 4 นิ้ว ลงถัง ST-1 — ใส่เป็นท่อโสโครก 2 นิ้ว ตามแบบ',
      '- **มาร์ก:** ประตูน้ำตัวกลาง GV-2 อยู่บนช่วงท่อ 2 นิ้ว (ถัง → ปั๊ม) แต่รายการประกอบแบบระบุประตูน้ำ 1 นิ้วอย่างเดียว — ใส่ 1 นิ้ว ทั้ง 3 ตัวตามรายการ',
      '', '## วิธีอ่าน', '',
      '- จุดอ้างอิง: เทียบลายผนังของแผ่น SN กับ A.2.01 (กริด 1 = ขอบลายผนัง +0.102 · กริด A = +0.296) ตรวจกับป้ายกริดในแผ่นแล้วตรง',
      '- ท่อประปา: เส้นชั้น WC01 ในบล็อก SET WC (เมน 1 นิ้ว ตามแนวผนัง) · ปลายเส้นแยก = จุดจ่ายน้ำ 38 จุด ตรงกับสัญลักษณ์จุดจ่ายน้ำ 38 ตัว',
      '- ท่อโสโครก: ชั้น SN04 · ท่อน้ำทิ้งและท่อโถปัสสาวะ: ชั้น SN02 (เส้นประ) · วงกลม r 0.05 = โถส้วม 9 · r 0.025 = จุดรับน้ำทิ้ง',
      '', '## รูป', '', '- `3d_สุขาภิบาล_บน.png` `3d_สุขาภิบาล_iso.png` `3d_สุขาภิบาล_หลัง.png` (ชุดแสดงผล "สุขาภิบาล")', '- `ตรวจ_SN201.png` `ตรวจ_SN202.png` แปลนจาก PDF ที่ใช้อ่าน', '']
open(os.path.join(H, 'ตารางตรวจ Step5.md'), 'w').write('\n'.join(L)); print(len(L))
